sys_script.script:
(function executeRule(current, previous /*null when async*/) {
    // FLEET-20: maintenance defaults and validation (D-01, D-13, D-15, D-16)
    var CLOSED = ['COMPLETED', 'CANCELLED'];
    var isInsert = current.operation() == 'insert';
    var state = current.getValue('maintenance_state');
    var entering = isInsert || current.maintenance_state.changes();
    var errors = [];

    // D-15: default expected_end_date = scheduled_date + maintenance.default_duration_days
    if (!current.scheduled_date.nil() && current.expected_end_date.nil()) {
        var days = parseInt(gs.getProperty('x_1850693_enterp_0.maintenance.default_duration_days', '1'), 10);
        var end = new GlideDate();
        end.setValue(current.getValue('scheduled_date'));
        end.addDaysUTC(isNaN(days) ? 1 : days);
        current.setValue('expected_end_date', end.getValue());
    }
    if (!current.scheduled_date.nil() && !current.expected_end_date.nil() &&
        current.getValue('expected_end_date') < current.getValue('scheduled_date')) {
        errors.push('Expected End Date cannot be before Scheduled Date.');
    }

    if (entering && state == 'SCHEDULED' && (current.scheduled_date.nil() || current.expected_end_date.nil())) {
        errors.push('Scheduled Date and Expected End Date are required to schedule maintenance.');
    }
    if (entering && state == 'COMPLETED' && current.getValue('maintenance_type') == 'PREVENTIVE' && current.service_odometer.nil()) {
        errors.push('Odometer at Service is required to complete preventive maintenance.');
    }

    if (errors.length) {
        for (var i = 0; i < errors.length; i++) {
            gs.addErrorMessage(errors[i]);
        }
        current.setAbortAction(true);
        return;
    }

    if (entering && state == 'IN_PROGRESS' && current.actual_start_date.nil()) {
        current.setValue('actual_start_date', new GlideDateTime().getValue());
    }
    if (entering && state == 'COMPLETED' && current.actual_end_date.nil()) {
        current.setValue('actual_end_date', new GlideDateTime().getValue());
    }

    if (current.short_description.nil()) {
        current.setValue('short_description', current.maintenance_type.getDisplayValue() + ' maintenance - ' +
            current.vehicle.getDisplayValue());
    }

    // D-01: task.active follows maintenance_state
    current.setValue('active', CLOSED.indexOf(state) < 0);
})(current, previous);
